"""Original finite RL arithmetic. No environment, network, optimizer or device."""
from __future__ import annotations

from dataclasses import dataclass
from fractions import Fraction
import math
import re
from typing import Any


def fields(value: Any, keys: set[str]) -> None:
    if not isinstance(value, dict) or set(value) != keys:
        raise ValueError('Unexpected or missing fields')


def rational(value: Any) -> Fraction:
    if not isinstance(value, str) or len(value) > 80 or not re.fullmatch(r'-?\d+(?:/\d+)?', value):
        raise ValueError('Expected bounded rational string, not boolean/nonfinite')
    try:
        return Fraction(value)
    except (ValueError, ZeroDivisionError) as exc:
        raise ValueError('Invalid rational') from exc


def name(value: Any) -> str:
    if not isinstance(value, str) or not re.fullmatch(r'[A-Za-z][A-Za-z0-9_]{0,20}', value):
        raise ValueError('Expected bounded state/action name')
    return value


def count(value: Any) -> int:
    if type(value) is not int or not 0 <= value <= 1000:
        raise ValueError('Expected integer count in0..1000')
    return value


def discount(value: Any) -> Fraction:
    result = rational(value)
    if not 0 <= result < 1:
        raise ValueError('This stationary discounted model requires0<=gamma<1')
    return result


def step_size(value: Any) -> Fraction:
    result = rational(value)
    if not 0 <= result <= 1:
        raise ValueError('Expected step size in0..1')
    return result


@dataclass(frozen=True)
class Model:
    states: tuple[str, ...]
    terminals: frozenset[str]
    gamma: Fraction
    transitions: dict[tuple[str, str], tuple[tuple[Fraction, str, Fraction], ...]]

    @classmethod
    def read(cls, raw: dict[str, Any]) -> 'Model':
        fields(raw, {'states', 'terminal_states', 'gamma', 'transitions'})
        if not isinstance(raw['states'], list) or not 1 <= len(raw['states']) <= 8:
            raise ValueError('Expected1..8 states')
        states = tuple(name(s) for s in raw['states'])
        if len(set(states)) != len(states):
            raise ValueError('Duplicate state')
        if not isinstance(raw['terminal_states'], list):
            raise ValueError('Expected terminal state list')
        terminals = frozenset(name(s) for s in raw['terminal_states'])
        if len(terminals) != len(raw['terminal_states']) or not terminals.issubset(states):
            raise ValueError('Invalid terminal states')
        gamma = discount(raw['gamma'])
        if not isinstance(raw['transitions'], list) or len(raw['transitions']) > 32:
            raise ValueError('Expected bounded transition list')
        transitions = {}
        for row in raw['transitions']:
            fields(row, {'state', 'action', 'outcomes'})
            state, action = name(row['state']), name(row['action'])
            if state not in states or state in terminals or (state, action) in transitions:
                raise ValueError('Unknown/terminal state or duplicate action')
            if not isinstance(row['outcomes'], list) or not 1 <= len(row['outcomes']) <= 8:
                raise ValueError('Expected1..8 outcomes')
            outcomes = []
            for outcome in row['outcomes']:
                fields(outcome, {'probability', 'next_state', 'reward'})
                probability, successor = rational(outcome['probability']), name(outcome['next_state'])
                if probability < 0 or successor not in states:
                    raise ValueError('Negative probability or unknown successor')
                outcomes.append((probability, successor, rational(outcome['reward'])))
            if sum(p for p, _, _ in outcomes) != 1:
                raise ValueError('Transition probability mass must be1')
            transitions[state, action] = tuple(outcomes)
        if any(not any(s == state for s, _ in transitions) for state in states if state not in terminals):
            raise ValueError('Nonterminal state has no action')
        return cls(states, terminals, gamma, transitions)

    def actions(self, state: str) -> list[str]:
        return sorted(a for s, a in self.transitions if s == state)

    def values(self, raw: dict[str, Any]) -> dict[str, Fraction]:
        fields(raw, set(self.states))
        values = {s: rational(raw[s]) for s in self.states}
        if any(values[s] != 0 for s in self.terminals):
            raise ValueError('Terminal values must be0')
        return values

    def policy(self, raw: dict[str, Any]) -> dict[str, dict[str, Fraction]]:
        fields(raw, set(self.states) - self.terminals)
        policy = {}
        for state in raw:
            fields(raw[state], set(self.actions(state)))
            probabilities = {a: rational(p) for a, p in raw[state].items()}
            if any(p < 0 for p in probabilities.values()) or sum(probabilities.values()) != 1:
                raise ValueError('Policy probabilities must be nonnegative and sum to1')
            policy[state] = probabilities
        return policy


def action_values(model: Model, values: dict[str, Fraction], state: str) -> dict[str, Fraction]:
    return {a: sum(p * (r + model.gamma * values[n]) for p, n, r in model.transitions[state, a])
            for a in model.actions(state)}


def evaluate_policy(model: Model, raw_policy: dict[str, Any]) -> dict[str, Fraction]:
    """Solve(I-gamma*P_pi)V=r_pi by exact Gaussian elimination."""
    policy = model.policy(raw_policy)
    states = [s for s in model.states if s not in model.terminals]
    size = len(states)
    index = {s: i for i, s in enumerate(states)}
    matrix = [[Fraction(int(i == j)) for j in range(size)] + [Fraction(0)] for i in range(size)]
    for state in states:
        row = matrix[index[state]]
        for action, weight in policy[state].items():
            for probability, successor, reward in model.transitions[state, action]:
                row[-1] += weight * probability * reward
                if successor in index:
                    row[index[successor]] -= model.gamma * weight * probability
    for column in range(size):
        pivot = next((i for i in range(column, size) if matrix[i][column]), None)
        if pivot is None:
            raise ValueError('Singular policy system')
        matrix[column], matrix[pivot] = matrix[pivot], matrix[column]
        divisor = matrix[column][column]
        matrix[column] = [x / divisor for x in matrix[column]]
        for i in range(size):
            if i != column:
                multiplier = matrix[i][column]
                matrix[i] = [x - multiplier * y for x, y in zip(matrix[i], matrix[column], strict=True)]
    return {s: matrix[index[s]][-1] if s in index else Fraction(0) for s in model.states}


def policy_residual(model: Model, raw_policy: dict[str, Any], values: dict[str, Fraction]) -> Fraction:
    policy = model.policy(raw_policy)
    return max((abs(sum(policy[s][a] * q for a, q in action_values(model, values, s).items()) - values[s])
                for s in policy), default=Fraction(0))


def optimal_step(model: Model, values: dict[str, Fraction], order: str | list[str]) -> dict[str, Fraction]:
    states = [s for s in model.states if s not in model.terminals]
    if order == 'synchronous':
        return {s: max(action_values(model, values, s).values()) if s in states else Fraction(0)
                for s in model.states}
    if not isinstance(order, list) or len(order) != len(states) or set(order) != set(states):
        raise ValueError('Expected a complete nonterminal permutation')
    updated = dict(values)
    for state in order:
        updated[state] = max(action_values(model, updated, state).values())
    return updated


def finite_horizon(model: Model, remaining_steps: Any) -> dict[str, Fraction]:
    values = {s: Fraction(0) for s in model.states}
    for _ in range(count(remaining_steps)):
        values = optimal_step(model, values, 'synchronous')
    return values


def greedy_actions(model: Model, values: dict[str, Fraction], state: str) -> list[str]:
    qs = action_values(model, values, state)
    return [a for a in qs if qs[a] == max(qs.values())] if qs else []


def read_episode(model: Model, raw: Any) -> list[dict[str, Any]]:
    if not isinstance(raw, list) or not 1 <= len(raw) <= 1000:
        raise ValueError('Expected complete bounded episode')
    episode = []
    previous = None
    for step in raw:
        fields(step, {'state', 'action', 'reward', 'next_state', 'terminated'})
        state, action, successor = name(step['state']), name(step['action']), name(step['next_state'])
        reward = rational(step['reward'])
        if previous is not None and state != previous:
            raise ValueError('Discontinuous episode')
        if type(step['terminated']) is not bool or step['terminated'] != (successor in model.terminals):
            raise ValueError('Terminal flag disagrees with declared model')
        outcomes = model.transitions.get((state, action), ())
        if not any(p > 0 and n == successor and r == reward for p, n, r in outcomes):
            raise ValueError('Observed transition absent from declared model')
        episode.append(dict(state=state, action=action, reward=reward,
                            next_state=successor, terminated=step['terminated']))
        previous = successor
    if not episode[-1]['terminated']:
        raise ValueError('MC examples require a complete episode')
    return episode


def returns(model: Model, episode: list[dict[str, Any]]) -> list[Fraction]:
    tail, values = Fraction(0), []
    for step in reversed(episode):
        tail = step['reward'] + model.gamma * tail
        values.append(tail)
    return list(reversed(values))


def mc_mean(model: Model, episodes: list[Any]) -> dict[str, Fraction]:
    totals: dict[str, Fraction] = {}
    visits: dict[str, int] = {}
    for raw in episodes:
        episode = read_episode(model, raw)
        for step, target in zip(episode, returns(model, episode), strict=True):
            state = step['state']
            totals[state] = totals.get(state, Fraction(0)) + target
            visits[state] = visits.get(state, 0) + 1
    return {s: totals[s] / visits[s] for s in sorted(totals)}


def update_episode(model: Model, raw: Any, values: dict[str, Fraction], alpha: Any,
                   method: str) -> dict[str, Fraction]:
    episode, rate = read_episode(model, raw), step_size(alpha)
    updated = dict(values)
    if method == 'mc':
        for step, target in zip(episode, returns(model, episode), strict=True):
            s = step['state']
            updated[s] += rate * (target - updated[s])
    elif method in {'td_forward', 'td_reverse_offline'}:
        for step in (episode if method == 'td_forward' else reversed(episode)):
            s, n = step['state'], step['next_state']
            target = step['reward'] + (0 if step['terminated'] else model.gamma * updated[n])
            updated[s] += rate * (target - updated[s])
    else:
        raise ValueError('Unknown update method')
    return updated


def interior_probability(value: Any) -> Fraction:
    result = rational(value)
    if not 0 < result < 1:
        raise ValueError('Expected positive support for both actions')
    return result


def bandit_score(p: Any, baseline: Any, action_dependent: bool = False) -> tuple[Fraction, Fraction]:
    probability, b = interior_probability(p), rational(baseline)
    terms = [(probability, (1 - probability) * (2 - (2 if action_dependent else b))),
             (1 - probability, -probability * (1 - (1 if action_dependent else b)))]
    mean = sum(weight * value for weight, value in terms)
    variance = sum(weight * (value - mean) ** 2 for weight, value in terms)
    return mean, variance


def ppo_objective(ratio: Any, advantage: Any, epsilon: Any) -> Fraction:
    r, a, e = rational(ratio), rational(advantage), rational(epsilon)
    if r < 0 or not 0 <= e < 1:
        raise ValueError('Invalid ratio or toy clipping width')
    return min(r * a, min(max(r, 1 - e), 1 + e) * a)


def ppo_mean(old_p: Any, new_p: Any, advantage_go: Any, advantage_stop: Any,
             epsilon: Any) -> Fraction:
    old, new = interior_probability(old_p), rational(new_p)
    if not 0 <= new <= 1:
        raise ValueError('Invalid new probability')
    return old * ppo_objective(str(new / old), advantage_go, epsilon) + (1 - old) * ppo_objective(
        str((1 - new) / (1 - old)), advantage_stop, epsilon)


def entropy_objective(p: Any, alpha: Any) -> tuple[float, float]:
    probability, coefficient = rational(p), rational(alpha)
    if not 0 <= probability <= 1 or coefficient < 0:
        raise ValueError('Invalid discrete entropy inputs')
    entropy = -sum(float(x) * math.log(float(x)) for x in [probability, 1 - probability] if x)
    return float(1 + probability) + float(coefficient) * entropy, entropy


def bootstrap(reward: Any, gamma: Any, next_value: Any, terminated: Any,
              truncated: Any) -> Fraction:
    if type(terminated) is not bool or type(truncated) is not bool:
        raise ValueError('Expected explicit boolean flags')
    r, g, value = rational(reward), discount(gamma), rational(next_value)
    return r if terminated else r + g * value


def entropy_backup(reward: Any, gamma: Any, q_estimates: list[Any], alpha: Any,
                   next_action_probability: Any, terminated: Any) -> float:
    """One supplied discrete entropy target, not a SAC learner or sampler."""
    if type(terminated) is not bool or not isinstance(q_estimates, list) or len(q_estimates) != 2:
        raise ValueError('Expected terminal flag and two supplied estimates')
    r, g = rational(reward), discount(gamma)
    qs, coefficient = [rational(q) for q in q_estimates], rational(alpha)
    probability = rational(next_action_probability)
    if coefficient < 0 or not 0 < probability <= 1:
        raise ValueError('Invalid entropy target inputs')
    return float(r) if terminated else float(r + g * min(qs)) - float(g * coefficient) * math.log(float(probability))
