from __future__ import annotations
from dataclasses import dataclass
from math import exp, isfinite, log1p, sqrt

def number(value: float) -> float:
    if type(value) not in (int, float) or not -1000 <= value <= 1000:
        raise ValueError("expected a finite built-in number in [-1000,1000]")
    return float(value)

def matrix(rows: list[list[float]]) -> list[list[float]]:
    if not isinstance(rows, (list, tuple)) or not 1 <= len(rows) <= 1000:
        raise ValueError("expected 1..1000 rows")
    if not isinstance(rows[0], (list, tuple)) or not 1 <= len(rows[0]) <= 8:
        raise ValueError("expected 1..8 features")
    width = len(rows[0])
    if any(not isinstance(row, (list, tuple)) or len(row) != width for row in rows):
        raise ValueError("ragged rows")
    return [[number(x) for x in row] for row in rows]

def data(rows: list[list[float]], targets: list[float]) -> tuple[list[list[float]], list[float]]:
    x = matrix(rows)
    if not isinstance(targets, (list, tuple)) or len(targets) != len(x):
        raise ValueError("one target per row required")
    return x, [number(y) for y in targets]
