def solve(a: list[list[float]], rhs: list[float]) -> list[float]:
    n = len(rhs)
    work = [list(row) + [value] for row, value in zip(a, rhs)]
    for column in range(n):
        pivot = max(range(column, n), key=lambda i: abs(work[i][column]))
        if abs(work[pivot][column]) < 1e-12:
            raise ValueError("singular or numerically small pivot")
        work[column], work[pivot] = work[pivot], work[column]
        scale = work[column][column]
        work[column] = [value / scale for value in work[column]]
        for i in range(n):
            if i != column:
                scale = work[i][column]
                work[i] = [u - scale * v for u, v in zip(work[i], work[column])]
    return [row[-1] for row in work]

def fit_poly(x: list[float], y: list[float], degree: int, lam: float = 0.0) -> list[float]:
    rows, y = data([[value] for value in x], y)
    lam = number(lam)
    if type(degree) is not int or not 0 <= degree <= 5 or lam < 0 or any(abs(row[0]) > 1 for row in rows):
        raise ValueError("polynomial demo requires degree0..5, |x|<=1 and nonnegative penalty")
    features = [[row[0] ** j for j in range(degree + 1)] for row in rows]
    n = len(rows)
    gram = [[sum(row[i] * row[j] for row in features) / n + (lam if i == j and i > 0 else 0.0)
             for j in range(degree + 1)] for i in range(degree + 1)]
    rhs = [sum(row[j] * target for row, target in zip(features, y)) / n for j in range(degree + 1)]
    return solve(gram, rhs)

def poly_predict(coefficients: list[float], x: float) -> float:
    result = 0.0
    for coefficient in reversed(coefficients):
        result = result * x + coefficient
    return result
