@dataclass(frozen=True)
class Tree:
    width: int
    value: float
    feature: int | None = None
    threshold: float = 0.0
    left: Tree | None = None
    right: Tree | None = None

def fit_tree(x: list[list[float]], y: list[float], depth: int = 2, min_leaf: int = 1) -> Tree:
    x, y = data(x, y)
    if type(depth) is not int or not 0 <= depth <= 5 or type(min_leaf) is not int or min_leaf < 1:
        raise ValueError("invalid tree limits")
    def sse(ids: list[int]) -> float:
        mean = sum(y[i] for i in ids) / len(ids)
        return sum((y[i] - mean) ** 2 for i in ids)
    def grow(ids: list[int], remaining: int) -> Tree:
        mean = sum(y[i] for i in ids) / len(ids)
        best, choice = sse(ids), None
        if remaining:
            for j in range(len(x[0])):
                values = sorted({x[i][j] for i in ids})
                for a, b in zip(values, values[1:]):
                    threshold = (a + b) / 2
                    left = [i for i in ids if x[i][j] <= threshold]
                    right = [i for i in ids if x[i][j] > threshold]
                    if min(len(left), len(right)) < min_leaf:
                        continue
                    score = sse(left) + sse(right)
                    if score < best - 1e-12:
                        best, choice = score, (j, threshold, left, right)
        if choice is None:
            return Tree(len(x[0]), mean)
        j, threshold, left, right = choice
        return Tree(len(x[0]), mean, j, threshold, grow(left, remaining - 1), grow(right, remaining - 1))
    return grow(list(range(len(x))), depth)

def tree_predict(tree: Tree, rows: list[list[float]]) -> list[float]:
    rows = matrix(rows)
    if len(rows[0]) != tree.width:
        raise ValueError("tree feature count changed")
    results = []
    for row in rows:
        node = tree
        while node.feature is not None:
            node = node.left if row[node.feature] <= node.threshold else node.right
            if node is None:
                raise ValueError("incomplete teaching tree")
        results.append(node.value)
    return results
