def kmeans(points: list[list[float]], initial: list[list[float]], max_iter: int = 100) -> tuple:
    points, centers = matrix(points), matrix(initial)
    if len(centers) > min(len(points), 8) or len(centers[0]) != len(points[0]) or type(max_iter) is not int or not 1 <= max_iter <= 1000:
        raise ValueError("invalid centers or iteration budget")
    def distance(a: list[float], b: list[float]) -> float:
        return sum((x - y) ** 2 for x, y in zip(a, b))
    def assign(current: list[list[float]]) -> list[int]:
        return [min(range(len(current)), key=lambda j: distance(point, current[j])) for point in points]
    def inertia(current: list[list[float]]) -> float:
        return sum(min(distance(point, center) for center in current) for point in points)
    history, converged = [inertia(centers)], False
    for _ in range(max_iter):
        labels, updated = assign(centers), []
        for j, old in enumerate(centers):
            members = [point for point, label in zip(points, labels) if label == j]
            updated.append([sum(point[c] for point in members) / len(members) for c in range(len(old))] if members else old[:])
        movement = max(distance(a, b) for a, b in zip(centers, updated))
        centers = updated
        history.append(inertia(centers))
        if movement <= 1e-24:
            converged = True
            break
    return centers, assign(centers), history, converged
