from __future__ import annotations
from math import exp, isfinite, log, sqrt, tanh

def finite(value: float) -> float:
    if type(value) not in (int, float) or not isfinite(value):
        raise ValueError("a finite built-in number is required")
    return float(value)

class Node:
    __slots__ = ("_value", "edges", "grad")

    @property
    def value(self) -> float:
        return self._value

    def __init__(self, value: float, edges: tuple = ()):
        self._value, self.edges, self.grad = finite(value), tuple(edges), 0.0

    @staticmethod
    def node(value: Node | float) -> Node:
        return value if isinstance(value, Node) else Node(value)

    def __add__(self, other: Node | float) -> Node:
        other = self.node(other)
        return Node(self.value + other.value, ((self, 1.0), (other, 1.0)))

    __radd__ = __add__

    def __mul__(self, other: Node | float) -> Node:
        other = self.node(other)
        return Node(self.value * other.value, ((self, other.value), (other, self.value)))

    __rmul__ = __mul__

    def __neg__(self) -> Node:
        return self * -1.0

    def __sub__(self, other: Node | float) -> Node:
        return self + -self.node(other)

    def relu(self) -> Node:
        return Node(max(0.0, self.value), ((self, float(self.value > 0)),))

    def tanh(self) -> Node:
        value = tanh(self.value)
        return Node(value, ((self, 1.0 - value * value),))

    def backward(self) -> None:
        order, seen, stack = [], set(), [(self, False)]
        while stack:
            node, expanded = stack.pop()
            if expanded:
                order.append(node)
            elif node not in seen:
                seen.add(node)
                if len(seen) > 20000:
                    raise ValueError("teaching graph exceeds 20000 nodes")
                stack.append((node, True))
                stack.extend((parent, False) for parent, _ in node.edges)
        adjoint = {node: 0.0 for node in order}
        adjoint[self] = 1.0
        for node in reversed(order):
            if not node.edges:
                node.grad += adjoint[node]
            for parent, local in node.edges:
                adjoint[parent] = finite(adjoint[parent] + adjoint[node] * local)

def zero_grad(parameters: list[Node]) -> None:
    for parameter in parameters:
        parameter.grad = 0.0
