```python
def checked(theta: list[float], rows: list[list[float]], targets: list[float]) -> tuple:
    if len(theta) != 9 or not 1 <= len(rows) <= 64 or len(targets) != len(rows):
        raise ValueError("need nine parameters, 1..64 rows and matched targets")
    if any(len(row) != 2 for row in rows):
        raise ValueError("need two features per row")
    theta = [finite(v) for v in theta]
    rows = [[finite(v) for v in row] for row in rows]
    targets = [finite(v) for v in targets]
    if any(abs(v) > 100 for v in theta + targets + [v for row in rows for v in row]):
        raise ValueError("teaching inputs/parameters restricted to [-100,100]")
    return theta, rows, targets

def activate(z, kind: str):
    if kind not in ("relu", "tanh"):
        raise ValueError("activation must be relu or tanh")
    if isinstance(z, Node):
        return z.relu() if kind == "relu" else z.tanh()
    return max(0.0, z) if kind == "relu" else tanh(z)

def forward(theta: list, row: list[float], kind: str):
    z = [theta[0] * row[0] + theta[1] * row[1] + theta[4],
         theta[2] * row[0] + theta[3] * row[1] + theta[5]]
    h = [activate(value, kind) for value in z]
    return theta[6] * h[0] + theta[7] * h[1] + theta[8], z, h

def manual(theta: list[float], rows: list[list[float]], targets: list[float], kind: str) -> tuple:
    theta, rows, targets = checked(theta, rows, targets)
    loss, gradient = 0.0, [0.0] * 9
    for row, target in zip(rows, targets):
        prediction, z, h = forward(theta, row, kind)
        error = prediction - target
        loss += 0.5 * error * error
        dz = [error * theta[6 + j] * (float(z[j] > 0) if kind == "relu" else 1 - h[j] ** 2) for j in range(2)]
        local = [dz[0] * row[0], dz[0] * row[1], dz[1] * row[0], dz[1] * row[1], dz[0], dz[1], error * h[0], error * h[1], error]
        gradient = [a + b for a, b in zip(gradient, local)]
    return loss / len(rows), [g / len(rows) for g in gradient]
