def dropout(values: list[float], mask: list[int], probability: float, training: bool = True) -> list[float]:
    probability = finite(probability)
    values = [finite(v) for v in values]
    if not values or not 0 <= probability <= 1 or type(training) is not bool:
        raise ValueError("invalid dropout inputs")
    if not training:
        return values[:]
    if len(mask) != len(values) or any(type(m) is not int or m not in (0, 1) for m in mask):
        raise ValueError("explicit binary mask required")
    if (probability == 0 and any(m != 1 for m in mask)) or (probability == 1 and any(mask)):
        raise ValueError("mask contradicts endpoint probability")
    return [0.0] * len(values) if probability == 1 else [v * m / (1 - probability) for v, m in zip(values, mask)]
