```python
def norm_rows(rows: list[list[float]]) -> list[list[float]]:
    if not 1 <= len(rows) <= 64 or not rows[0] or any(len(row) != len(rows[0]) for row in rows):
        raise ValueError("need a nonempty rectangular batch")
    result = [[finite(value) for value in row] for row in rows]
    if len(result[0]) > 8 or any(abs(v) > 100 for row in result for v in row):
        raise ValueError("normalization demo needs 1..8 features in [-100,100]")
    return result

class BatchNorm:
    def __init__(self, width: int, momentum: float = 0.5, eps: float = 1e-5):
        momentum, eps = finite(momentum), finite(eps)
        if type(width) is not int or not 1 <= width <= 8 or not 0 <= momentum <= 1 or eps <= 0:
            raise ValueError("invalid normalization settings")
        self.mean, self.variance = [0.0] * width, [1.0] * width
        self.momentum, self.eps = momentum, eps

    def apply(self, rows: list[list[float]], training: bool) -> list[list[float]]:
        rows = norm_rows(rows)
        if len(rows[0]) != len(self.mean) or type(training) is not bool or (training and len(rows) < 2):
            raise ValueError("incompatible batch; training needs at least two rows")
        if training:
            n = len(rows)
            means = [sum(row[j] for row in rows) / n for j in range(len(self.mean))]
            variances = [sum((row[j] - mean) ** 2 for row in rows) / n for j, mean in enumerate(means)]
            m = self.momentum
            self.mean = [(1 - m) * old + m * new for old, new in zip(self.mean, means)]
            self.variance = [(1 - m) * old + m * new * n / (n - 1) for old, new in zip(self.variance, variances)]
        else:
            means, variances = self.mean, self.variance
        return [[(v - mean) / sqrt(var + self.eps) for v, mean, var in zip(row, means, variances)] for row in rows]

def layer_norm(rows: list[list[float]], eps: float = 1e-5) -> list[list[float]]:
    rows, eps = norm_rows(rows), finite(eps)
    if eps <= 0:
        raise ValueError("positive eps required")
    result = []
    for row in rows:
        mean = sum(row) / len(row)
        variance = sum((v - mean) ** 2 for v in row) / len(row)
        result.append([(v - mean) / sqrt(variance + eps) for v in row])
    return result
