from math import exp, isfinite, log, tanh

def number(value: float) -> float:
    if type(value) not in (int, float) or not isfinite(value) or abs(value) > 100:
        raise ValueError("finite built-in number in [-100,100] required")
    return float(value)

def volume(value: list) -> list:
    if not isinstance(value, (list, tuple)) or not 1 <= len(value) <= 4:
        raise ValueError("need 1..4 channels")
    if not isinstance(value[0], (list, tuple)) or not 1 <= len(value[0]) <= 12:
        raise ValueError("need 1..12 rows")
    if not isinstance(value[0][0], (list, tuple)) or not 1 <= len(value[0][0]) <= 12:
        raise ValueError("need 1..12 columns")
    height, width = len(value[0]), len(value[0][0])
    if any(not isinstance(c, (list, tuple)) or len(c) != height or
           any(not isinstance(row, (list, tuple)) or len(row) != width for row in c)
           for c in value):
        raise ValueError("inconsistent channel shapes")
    return [[[number(v) for v in row] for row in channel] for channel in value]

def zeros(channels: int, height: int, width: int) -> list:
    return [[[0.0 for _ in range(width)] for _ in range(height)] for _ in range(channels)]
