def conv_shape(x: list, kernels: list, bias: list, stride: int, padding: int) -> tuple:
    x = volume(x)
    if not isinstance(kernels, (list, tuple)) or not 1 <= len(kernels) <= 4:
        raise ValueError("need 1..4 filters")
    kernels = [volume(k) for k in kernels]
    shape = (len(kernels[0]), len(kernels[0][0]), len(kernels[0][0][0]))
    if shape[0] != len(x) or any((len(k), len(k[0]), len(k[0][0])) != shape for k in kernels):
        raise ValueError("kernel channels or sizes disagree")
    if type(stride) is not int or not 1 <= stride <= 3 or type(padding) is not int or not 0 <= padding <= 2:
        raise ValueError("invalid stride or each-side padding")
    if len(bias) != len(kernels):
        raise ValueError("one bias per output channel required")
    bias = [number(v) for v in bias]
    kh, kw = shape[1:]
    oh = (len(x[0]) + 2 * padding - kh) // stride + 1
    ow = (len(x[0][0]) + 2 * padding - kw) // stride + 1
    if min(oh, ow) <= 0 or max(oh, ow) > 12:
        raise ValueError("no valid window or teaching output too large")
    return x, kernels, bias, kh, kw, oh, ow

def correlate(x: list, kernels: list, bias: list, stride: int = 1, padding: int = 0) -> list:
    x, kernels, bias, kh, kw, oh, ow = conv_shape(x, kernels, bias, stride, padding)
    result = zeros(len(kernels), oh, ow)
    for o, kernel in enumerate(kernels):
        for i in range(oh):
            for j in range(ow):
                total = bias[o]
                for c in range(len(x)):
                    for a in range(kh):
                        for b in range(kw):
                            row, col = i * stride + a - padding, j * stride + b - padding
                            if 0 <= row < len(x[0]) and 0 <= col < len(x[0][0]):
                                total += kernel[c][a][b] * x[c][row][col]
                result[o][i][j] = total
    return result
