def conv_backward(x: list, kernels: list, upstream: list, stride: int = 1, padding: int = 0) -> tuple:
    x, kernels, _, kh, kw, oh, ow = conv_shape(x, kernels, [0]*len(kernels), stride, padding)
    upstream = volume(upstream)
    if (len(upstream), len(upstream[0]), len(upstream[0][0])) != (len(kernels), oh, ow):
        raise ValueError("upstream gradient shape changed")
    dx, dk, db = zeros(len(x), len(x[0]), len(x[0][0])), [], [0.0]*len(kernels)
    for o, kernel in enumerate(kernels):
        current = zeros(len(x), kh, kw)
        for i in range(oh):
            for j in range(ow):
                g = upstream[o][i][j]
                db[o] += g
                for c in range(len(x)):
                    for a in range(kh):
                        for b in range(kw):
                            row, col = i*stride+a-padding, j*stride+b-padding
                            if 0 <= row < len(x[0]) and 0 <= col < len(x[0][0]):
                                current[c][a][b] += g*x[c][row][col]
                                dx[c][row][col] += g*kernel[c][a][b]
        dk.append(current)
    return dx, dk, db
