def pool(x: list, window: int = 2, stride: int = 2, mode: str = "max") -> tuple:
    x = volume(x)
    if type(window) is not int or not 1 <= window <= 4 or type(stride) is not int or not 1 <= stride <= 3:
        raise ValueError("invalid pooling window or stride")
    if mode not in ("max", "mean"):
        raise ValueError("invalid pooling mode")
    oh, ow = (len(x[0])-window)//stride+1, (len(x[0][0])-window)//stride+1
    if min(oh, ow) <= 0:
        raise ValueError("no pooling window fits")
    out, routes = zeros(len(x), oh, ow), []
    for c, channel in enumerate(x):
        for i in range(oh):
            for j in range(ow):
                cells = [(i*stride+a, j*stride+b) for a in range(window) for b in range(window)]
                if mode == "max":
                    chosen = max(cells, key=lambda rc: channel[rc[0]][rc[1]])
                    out[c][i][j] = channel[chosen[0]][chosen[1]]
                    routes.append((c, i, j, [(chosen[0], chosen[1], 1.0)]))
                else:
                    out[c][i][j] = sum(channel[r][q] for r, q in cells) / len(cells)
                    routes.append((c, i, j, [(r, q, 1/len(cells)) for r, q in cells]))
    return out, routes

def pool_backward(x: list, upstream: list, window: int = 2, stride: int = 2, mode: str = "max") -> list:
    out, routes = pool(x, window, stride, mode)
    x, upstream = volume(x), volume(upstream)
    if (len(upstream), len(upstream[0]), len(upstream[0][0])) != (len(out), len(out[0]), len(out[0][0])):
        raise ValueError("upstream pooling shape changed")
    dx = zeros(len(x), len(x[0]), len(x[0][0]))
    for c, i, j, cells in routes:
        for r, q, weight in cells:
            dx[c][r][q] += upstream[c][i][j] * weight
    return dx
