from copy import deepcopy
from hashlib import sha256
import json
from math import sqrt
from random import Random
from vision import classifier

def digest(value: list) -> str:
    return sha256(json.dumps(value, separators=(",", ":")).encode()).hexdigest()

def bar(axis: int, row: int, col: int, inverted: bool = False) -> list:
    if type(axis) is not int or axis not in (0, 1) or type(inverted) is not bool:
        raise ValueError("invalid fictional pattern")
    if type(row) is not int or type(col) is not int or not 0 <= row <= 5 or not 0 <= col <= 5:
        raise ValueError("invalid start")
    if row+(3 if axis else 1)>6 or col+(1 if axis else 3)>6:
        raise ValueError("bar exceeds image")
    background, foreground = (0.7, 0.1) if inverted else (0.0, 1.0)
    image = [[background for _ in range(6)] for _ in range(6)]
    for i in range(3):
        image[row+(i if axis else 0)][col+(0 if axis else i)] = foreground
    return [image]

def flip(image: list) -> list:
    return [[list(reversed(row)) for row in channel] for channel in image]

def patterns(positions: list[tuple[int, int]], inverted: bool, prefix: str) -> list[dict]:
    return [dict(id=f"{prefix}-{axis}-{r}-{c}", label=axis, pixels=bar(axis,r,c,inverted))
            for axis in range(2) for r,c in positions]

def evaluate(theta: list[float], data: list[dict]) -> dict:
    losses, correct = [], 0
    for sample in data:
        loss, _, _ = classifier(theta, sample["pixels"], sample["label"])
        prediction = classifier(theta, sample["pixels"])
        correct += int(max(range(2),key=lambda i:prediction[i])==sample["label"])
        losses.append(loss)
    return dict(loss=sum(losses)/len(losses), correct=correct, total=len(data))

def fit(initial: list[float], data: list[dict], epochs: int, rate: float,
        frozen: bool = False, augmented: bool = False, validation: list[dict] | None = None) -> dict:
    if type(epochs) is not int or not 1<=epochs<=500 or type(frozen) is not bool or type(augmented) is not bool:
        raise ValueError("invalid fixed training budget")
    if type(rate) not in (int,float) or not 0<rate<=0.5 or not data:
        raise ValueError("invalid learning rate or dataset")
    theta, original = initial[:], digest(initial[:20])
    batch = [(s["pixels"],s["label"]) for s in data]
    batch += [(flip(s["pixels"]) if augmented else deepcopy(s["pixels"]),s["label"]) for s in data]
    best, best_epoch, best_theta = (evaluate(theta,validation)["loss"] if validation else None),0,theta[:]
    curve = []
    for epoch in range(1,epochs+1):
        gradient = [0.0]*26
        for image,label in batch:
            _, current, _ = classifier(theta,image,label)
            gradient = [a+b/len(batch) for a,b in zip(gradient,current)]
        theta = [w-rate*g if not frozen or i>=20 else w for i,(w,g) in enumerate(zip(theta,gradient))]
        record = dict(epoch=epoch,training=evaluate(theta,data),
                      computed_gradient_norm=sqrt(sum(g*g for g in gradient)),
                      update_norm=rate*sqrt(sum(g*g for i,g in enumerate(gradient) if not frozen or i>=20)))
        if validation:
            record["validation"] = evaluate(theta,validation)
            if record["validation"]["loss"] < best:
                best,best_epoch,best_theta = record["validation"]["loss"],epoch,theta[:]
        curve.append(record)
    if not validation:
        best_epoch,best_theta = epochs,theta[:]
    if frozen:
        assert digest(theta[:20])==original and digest(best_theta[:20])==original
    return dict(theta=theta,selected_theta=best_theta,selected_epoch=best_epoch,
                selected_validation_loss=best,feature_hash_before=original,
                feature_hash_after=digest(theta[:20]),exposures_per_epoch=len(batch),curve=curve)

def run() -> dict:
    source_data=patterns([(r,c) for r in range(4) for c in range(4)],False,"source")
    training=patterns([(0,0),(1,1)],True,"target-train")
    validation=patterns([(2,0),(3,2)],True,"target-validation")
    final=patterns([(0,1),(1,0)],True,"target-final")
    original=deepcopy((source_data,training,validation,final))
    train_bytes={digest(s["pixels"]) for s in training}
    augmented_bytes=train_bytes|{digest(flip(s["pixels"])) for s in training}
    validation_bytes={digest(s["pixels"]) for s in validation}
    final_bytes={digest(s["pixels"]) for s in final}
    assert not augmented_bytes & (validation_bytes|final_bytes) and not validation_bytes & final_bytes
    rng=Random(20261020)
    initial=[rng.uniform(-0.2,0.2) for _ in range(18)]+[0.0,0.0,.2,-.2,-.2,.2,0.0,0.0]
    pretrained=fit(initial,source_data,500,.2)
    pretrained_features=pretrained["theta"][:20]
    fresh_head=[.2,-.2,-.2,.2,0.0,0.0]
    arms=[]
    for mode in ["scratch","frozen","finetune"]:
        for augmented in [False,True]:
            start=(initial[:20] if mode=="scratch" else pretrained_features[:])+fresh_head[:]
            record=fit(start,training,250,.2,mode=="frozen",augmented,validation)
            selected=evaluate(record["selected_theta"],validation)
            arms.append(dict(name=mode+("_flip" if augmented else "_plain"),
                             selected_validation=selected,record=record))
    winner=min(arms,key=lambda a:(a["selected_validation"]["loss"],a["name"]))
    # The final fixture is evaluated for the selected arm only, after selection.
    final_result=evaluate(winner["record"]["selected_theta"],final)
    assert original==(source_data,training,validation,final)
    return dict(status="EXECUTED_FICTIONAL_VISION_EXPERIMENT",seed=20261020,
                source_examples=len(source_data),source_epochs=500,source_result=evaluate(pretrained["theta"],source_data),
                target_examples=dict(training=len(training),validation=len(validation),final=len(final)),
                target_epochs=250,target_exposures_per_epoch=8,predeclared_arms=6,
                selection="minimum validation crossentropy; exact ties use arm name; earliest best checkpoint per arm",
                selected_arm=winner["name"],final_result=final_result,arms=arms,
                limits="Known synthetic bar templates and generator rules; related objects/templates remain across domains despite no exact target pixel duplicates. Not blinded, independent objects, real images or a population performance estimate. Target exposure budgets equal; transfer additionally used source pretraining. Frozen arms still compute all gradients and mask only updates, so no compute-saving claim. No real framework or external model calls.")

if __name__ == "__main__":
    print(json.dumps(run(),indent=2))
