"""Original bounded scalar teaching model; Python standard library only."""
from __future__ import annotations
import math
import random


class Node:
    def __init__(self, value: float, parents: tuple = ()) -> None:
        self.v = float(value)
        if not math.isfinite(self.v):
            raise ValueError('nonfinite node')
        self.parents = parents
        self.g = 0.0

    def __add__(self, other):
        other = node(other)
        return Node(self.v + other.v, ((self, 1.0), (other, 1.0)))

    __radd__ = __add__

    def __mul__(self, other):
        other = node(other)
        return Node(self.v * other.v, ((self, other.v), (other, self.v)))

    __rmul__ = __mul__

    def __neg__(self):
        return self * -1.0

    def __sub__(self, other):
        return self + -node(other)

    def __truediv__(self, other):
        return self * node(other).power(-1.0)

    def power(self, exponent: float):
        if self.v <= 0:
            raise ValueError('power requires positive base')
        return Node(self.v ** exponent,
                    ((self, exponent * self.v ** (exponent - 1.0)),))

    def exp(self):
        value = math.exp(self.v)
        return Node(value, ((self, value),))

    def log(self):
        if self.v <= 0:
            raise ValueError('log requires positive input')
        return Node(math.log(self.v), ((self, 1.0 / self.v),))

    def tanh(self):
        value = math.tanh(self.v)
        return Node(value, ((self, 1.0 - value * value),))

    def relu(self):
        return Node(max(0.0, self.v), ((self, float(self.v > 0)),))

    def backward(self) -> None:
        ordered, seen, stack = [], set(), [(self, False)]
        while stack:
            current, expanded = stack.pop()
            if expanded:
                ordered.append(current)
            elif current not in seen:
                seen.add(current)
                stack.append((current, True))
                stack.extend((parent, False) for parent, _ in current.parents)
        for current in ordered:
            current.g = 0.0
        self.g = 1.0
        for current in reversed(ordered):
            for parent, derivative in current.parents:
                parent.g += current.g * derivative
