def node(value) -> Node:
    return value if isinstance(value, Node) else Node(value)


def softmax(values: list[Node]) -> list[Node]:
    if not values:
        raise ValueError('softmax needs a nonempty visible set')
    shift = max(x.v for x in values)
    exps = [(x - shift).exp() for x in values]
    total = sum(exps)
    return [x / total for x in exps]


def crossentropy(logits: list[Node], target: int) -> Node:
    if type(target) is not int or not 0 <= target < len(logits):
        raise ValueError('invalid target')
    shift = max(x.v for x in logits)
    return sum((x - shift).exp() for x in logits).log() + shift - logits[target]


def attention(scores: list[float], values: list[float], visible: int):
    if (type(visible) is not int or not 1 <= visible <= len(scores) or len(scores) != len(values)
            or any(type(x) not in (int, float) or not math.isfinite(x)
                   for x in scores + values)):
        raise ValueError('invalid attention fixture')
    weights = softmax([Node(x) for x in scores[:visible]])
    return [x.v for x in weights], sum(w.v * x for w, x in zip(weights, values))


def recurrent(inputs: list[Node], a: Node, b: Node, c: Node, initial: Node):
    states, h = [], initial
    for x in inputs:
        h = (a * h + b * x + c).tanh()
        states.append(h)
    return states


VOCAB = '甲乙丙'
CYCLE = [0, 1, 0, 2]
CASES = [(tuple(CYCLE[(p + k) % 4] for k in range(3)), CYCLE[(p + 3) % 4])
         for p in range(4)]


def encode(text: str) -> list[int]:
    if not text or any(ch not in VOCAB for ch in text):
        raise ValueError('only the three fixed code points are supported')
    return [VOCAB.index(ch) for ch in text]
