        keys = [self.linear(row, self.k) for row in x]
        values = [self.linear(row, self.v) for row in x]
        logits, trace = [], []
        for t, row in enumerate(x):
            joined, row_trace = [], []
            for head in range(2):
                start = 2 * head
                scores = [sum(queries[t][d] * keys[j][d] for d in range(start, start + 2))
                          / math.sqrt(2) for j in range(t + 1)]
                weights = softmax(scores)
                joined.extend(sum(weights[j] * values[j][d] for j in range(t + 1))
                              for d in range(start, start + 2))
                row_trace.append(weights)
            projected = self.linear(joined, self.out)
            first = self.normalize([a + b for a, b in zip(row, projected)], self.g1, self.n1)
            hidden = [z.relu() for z in self.linear(first, self.f1, self.b1)]
            feed = self.linear(hidden, self.f2, self.b2)
            second = self.normalize([a + b for a, b in zip(first, feed)], self.g2, self.n2)
            logits.append(self.linear(second, self.head, self.bias))
            trace.append(row_trace)
        return logits, trace

    def zero(self) -> None:
        for p in self.named.values():
            p.g = 0.0

    def generate(self, prefix: str, count: int) -> str:
        ids = encode(prefix)
        if type(count) is not int or not 0 <= count <= 24:
            raise ValueError('generation length must be between zero and 24')
        for _ in range(count):
            logits, _ = self(ids[-3:])
            ids.append(max(range(3), key=lambda j: logits[-1][j].v))
        return ''.join(VOCAB[i] for i in ids)
