"""Original two-dimensional Gaussian conditional-flow teaching model.

No neural network, downloaded model, image data or external service is used.
"""
from bisect import bisect_right
import json
import math
import random

MU = (2.0, -1.0)
STD = (2.0, 0.5)
SIGMA_MIN = 0.25
C = 1.0 - SIGMA_MIN
TIMES = (0.0, 0.25, 0.5, 0.75, 1.0)


def finite_vector(x):
    if len(x) != 2 or any(isinstance(v, bool) or not math.isfinite(v) for v in x):
        raise ValueError("Expected two finite real coordinates")


def time_value(t):
    if isinstance(t, bool) or not math.isfinite(t) or not 0 <= t <= 1:
        raise ValueError("Time must be in [0, 1]")


def path_moments(t, j):
    time_value(t)
    if j not in (0, 1):
        raise ValueError("Coordinate must be 0 or 1")
    a = 1 - C * t
    return t * MU[j], a * a + t * t * STD[j] ** 2


def exact_coefficients(t, j):
    mean, variance = path_moments(t, j)
    covariance = -C * (1 - C * t) + t * STD[j] ** 2
    slope = covariance / variance
    return slope, MU[j] - slope * mean


def pairs(n, seed):
    rng = random.Random(seed)
    result = []
    for _ in range(n):
        z = tuple(rng.gauss(0, 1) for _ in range(2))
        y = tuple(MU[j] + STD[j] * rng.gauss(0, 1) for j in range(2))
        result.append((z, y))
    return result


def conditional_pair(t, pair):
    time_value(t)
    z, y = pair
    finite_vector(z)
    finite_vector(y)
    return (tuple((1 - C * t) * z[j] + t * y[j] for j in range(2)),
            tuple(y[j] - C * z[j] for j in range(2)))


def mse(data, t, coefficients):
    total = 0.0
    for pair in data:
        x, target = conditional_pair(t, pair)
        total += sum((coefficients[j][0] * x[j] + coefficients[j][1] - target[j]) ** 2
                     for j in range(2))
    return total / (2 * len(data))


def fit(data):
    if len(data) < 2:
        raise ValueError("Need at least two pairs")
    fitted, rows = [], []
    for t in TIMES:
        transformed = [conditional_pair(t, p) for p in data]
        coefficients = []
        for j in range(2):
            xm = sum(x[j] for x, _ in transformed) / len(data)
            um = sum(u[j] for _, u in transformed) / len(data)
            variance = sum((x[j] - xm) ** 2 for x, _ in transformed)
            if variance <= 0:
                raise ValueError("Degenerate least-squares input")
            covariance = sum((x[j] - xm) * (u[j] - um) for x, u in transformed)
            slope = covariance / variance
            coefficients.append((slope, um - slope * xm))
        fitted.append(coefficients)
        analytic = [exact_coefficients(t, j) for j in range(2)]
        floor = sum(STD[j] ** 2 + C * C
                    - (-C * (1 - C * t) + t * STD[j] ** 2) ** 2 / path_moments(t, j)[1]
                    for j in range(2)) / 2
        rows.append(dict(t=t, coefficients=coefficients, analytic_coefficients=analytic,
                         train_mse=mse(data, t, coefficients),
                         population_conditional_mse_floor=floor))
    return fitted, rows


def interpolated_coefficients(t, fitted):
    time_value(t)
    if len(fitted) != len(TIMES) or any(len(row) != 2 for row in fitted):
        raise ValueError("Expected the declared coefficient grid")
    i = min(len(TIMES) - 2, max(0, bisect_right(TIMES, t) - 1))
    weight = (t - TIMES[i]) / (TIMES[i + 1] - TIMES[i])
    return [tuple((1 - weight) * fitted[i][j][k] + weight * fitted[i + 1][j][k]
                  for k in range(2)) for j in range(2)]


def velocity(t, x, fitted=None):
    finite_vector(x)
    coefficients = ([exact_coefficients(t, j) for j in range(2)] if fitted is None
                    else interpolated_coefficients(t, fitted))
    return tuple(coefficients[j][0] * x[j] + coefficients[j][1] for j in range(2))


def advance(t, x, h, method, fitted=None):
    first = velocity(t, x, fitted)
    predicted = tuple(x[j] + h * first[j] for j in range(2))
    if method == "euler":
        return predicted
    if method != "heun":
        raise ValueError("Unknown integration method")
    second = velocity(min(1.0, t + h), predicted, fitted)
    return tuple(x[j] + h * (first[j] + second[j]) / 2 for j in range(2))


def solve(z, steps, method, fitted=None):
    finite_vector(z)
    if isinstance(steps, bool) or not isinstance(steps, int) or steps <= 0:
        raise ValueError("Steps must be a positive integer")
    if method not in {"euler", "heun"}:
        raise ValueError("Unknown integration method")
    x = z
    for i in range(steps):
        x = advance(i / steps, x, 1 / steps, method, fitted)
    return x


def exact_trajectory(t, z):
    finite_vector(z)
    return tuple(path_moments(t, j)[0] + math.sqrt(path_moments(t, j)[1]) * z[j]
                 for j in range(2))


def moments(samples):
    means = [sum(x[j] for x in samples) / len(samples) for j in range(2)]
    variances = [sum((x[j] - means[j]) ** 2 for x in samples) / len(samples)
                 for j in range(2)]
    return dict(mean=means, variance_divisor_n=variances)


def experiment():
    training = pairs(4096, 20261020)
    diagnostic = pairs(1024, 20261022)
    fitted, fit_rows = fit(training)
    for row in fit_rows:
        row["diagnostic_mse"] = mse(diagnostic, row["t"], row["coefficients"])
        row["diagnostic_analytic_mse"] = mse(diagnostic, row["t"], row["analytic_coefficients"])
    rng = random.Random(20261021)
    starts = [tuple(rng.gauss(0, 1) for _ in range(2)) for _ in range(4096)]
    exact_end = [exact_trajectory(1.0, z) for z in starts]
    rows = []
    arms = [("euler", n) for n in (4, 16, 64, 256)] + [("heun", n) for n in (8, 32, 128)]
    for label, coefficients in [("analytic", None), ("learned-time-interpolated", fitted)]:
        for method, steps in arms:
            ends = [solve(z, steps, method, coefficients) for z in starts]
            error = math.sqrt(sum((a[j] - b[j]) ** 2 for a, b in zip(ends, exact_end)
                                  for j in range(2)) / (2 * len(starts)))
            rows.append(dict(field=label, method=method, steps=steps,
                             field_evaluations=steps * (2 if method == "heun" else 1),
                             coupled_endpoint_rmse=error, **moments(ends)))
    return dict(fit_rows=fit_rows, coefficient_count=20, training_pairs=4096,
                diagnostic_pairs=1024, sampling_count=4096,
                target_mean=list(MU), target_variance=[s * s + SIGMA_MIN ** 2 for s in STD],
                raw_data_variance=[s * s for s in STD], exact_same_starts=moments(exact_end),
                sampling_arms=rows, model_or_step_selection=False)


if __name__ == "__main__":
    print(json.dumps(experiment(), ensure_ascii=False, indent=2))
